-- =====================================================================
-- SOURCE: schema.sql
-- =====================================================================

-- Personal Finance — Supabase schema
-- Run this in the Supabase SQL editor for a fresh project.

-- =========================
-- Tables
-- =========================
create table if not exists public.accounts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  balance numeric(12,2) not null default 0,
  created_at timestamptz not null default now(),
  unique (user_id, name)
);

create table if not exists public.ai_chats (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  question text not null,
  answer text not null,
  created_at timestamptz not null default now()
);

create index if not exists ai_chats_user_created_idx
  on public.ai_chats (user_id, created_at desc);

alter table public.ai_chats enable row level security;

drop policy if exists "ai_chats_owner_all" on public.ai_chats;
create policy "ai_chats_owner_all" on public.ai_chats
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

create table if not exists public.transactions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  account_id uuid not null references public.accounts(id) on delete cascade,
  type text not null check (type in ('Income','Expense')),
  amount numeric(12,2) not null check (amount > 0),
  category text not null,
  description text,
  date date not null,
  created_at timestamptz not null default now()
);

create index if not exists transactions_user_date_idx
  on public.transactions (user_id, date desc);

create index if not exists transactions_account_idx
  on public.transactions (account_id);

-- =========================
-- Row Level Security
-- =========================
alter table public.accounts enable row level security;
alter table public.transactions enable row level security;

drop policy if exists "accounts_owner_all" on public.accounts;
create policy "accounts_owner_all" on public.accounts
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

drop policy if exists "transactions_owner_all" on public.transactions;
create policy "transactions_owner_all" on public.transactions
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- =========================
-- Default accounts on signup
-- =========================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.accounts (user_id, name, balance) values
    (new.id, 'Fidelity Account', 0),
    (new.id, 'Access Account',   0),
    (new.id, 'Mobile Money',     0),
    (new.id, 'Cash',             0);
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- =========================
-- Balance maintenance
-- Recompute affected account balances after txn changes.
-- =========================
create or replace function public.recompute_account_balance(p_account uuid)
returns void
language plpgsql
as $$
begin
  update public.accounts a
     set balance = coalesce((
       select sum(case when t.type = 'Income' then t.amount else -t.amount end)
       from public.transactions t
       where t.account_id = a.id
     ), 0)
   where a.id = p_account;
end;
$$;

create or replace function public.transactions_balance_trigger()
returns trigger
language plpgsql
as $$
begin
  if (tg_op = 'INSERT') then
    perform public.recompute_account_balance(new.account_id);
  elsif (tg_op = 'UPDATE') then
    perform public.recompute_account_balance(new.account_id);
    if new.account_id <> old.account_id then
      perform public.recompute_account_balance(old.account_id);
    end if;
  elsif (tg_op = 'DELETE') then
    perform public.recompute_account_balance(old.account_id);
  end if;
  return null;
end;
$$;

drop trigger if exists trg_transactions_balance on public.transactions;
create trigger trg_transactions_balance
  after insert or update or delete on public.transactions
  for each row execute function public.transactions_balance_trigger();


-- =====================================================================
-- SOURCE: migrations/0002_money_foundation.sql
-- =====================================================================

-- Personal Finance — Money foundation
--
-- Gives the app enough structure to answer questions it previously could not:
--   "how much of this is actually spendable?"i  -> accounts.liquidity + min_balance
--   "what is already committed?"               -> obligations
--   "where should I pay this from?"            -> account metadata + obligations
--   "move money from here to there"            -> transactions.type = 'Transfer'
--
-- Safe to run more than once. Run after 0001 (schema.sql).

-- =========================================================================
-- 1. Account metadata
-- =========================================================================
alter table public.accounts
  add column if not exists kind text not null default 'bank',
  add column if not exists liquidity text not null default 'liquid',
  add column if not exists min_balance numeric(12,2) not null default 0,
  add column if not exists purpose text,
  add column if not exists is_archived boolean not null default false,
  add column if not exists sort_order integer not null default 0;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'accounts_kind_check') then
    alter table public.accounts add constraint accounts_kind_check
      check (kind in ('bank','momo','cash','savings','investment','credit'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_liquidity_check') then
    alter table public.accounts add constraint accounts_liquidity_check
      check (liquidity in ('liquid','reserved','locked'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_min_balance_check') then
    alter table public.accounts add constraint accounts_min_balance_check
      check (min_balance >= 0);
  end if;
end $$;

-- Opening balance, added separately so we can backfill it exactly once.
--
-- Why this matters: recompute_account_balance() overwrites accounts.balance with
-- the sum of transactions. Any balance a user typed in by hand (a starting
-- balance, or a manual correction) was silently erased the next time a
-- transaction on that account changed. Storing it explicitly makes the recompute
-- lossless.
do $$
declare
  v_fresh boolean;
begin
  v_fresh := not exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name  = 'accounts'
      and column_name = 'opening_balance'
  );

  if v_fresh then
    alter table public.accounts
      add column opening_balance numeric(12,2) not null default 0;

    -- Preserve every currently displayed balance: whatever the balance is now
    -- that transactions do not explain becomes the opening balance.
    update public.accounts a
       set opening_balance = a.balance - coalesce((
             select sum(case when t.type = 'Income' then t.amount else -t.amount end)
             from public.transactions t
             where t.account_id = a.id
           ), 0);
  end if;
end $$;

-- =========================================================================
-- 2. Transfers as a first-class transaction type
-- =========================================================================
-- Previously a transfer was faked as an Expense on the source plus an Income on
-- the destination, both tagged category 'Transfer'. That double-counted into
-- every income/expense figure in the app and showed up in the spending pie as
-- if moving your own money were a purchase.
alter table public.transactions
  add column if not exists to_account_id uuid references public.accounts(id) on delete cascade;

alter table public.transactions drop constraint if exists transactions_type_check;
alter table public.transactions add constraint transactions_type_check
  check (type in ('Income','Expense','Transfer'));

alter table public.transactions drop constraint if exists transactions_transfer_shape_check;
alter table public.transactions add constraint transactions_transfer_shape_check
  check (
    (type = 'Transfer' and to_account_id is not null and to_account_id <> account_id)
    or
    (type <> 'Transfer' and to_account_id is null)
  );

create index if not exists transactions_to_account_idx
  on public.transactions (to_account_id) where to_account_id is not null;

-- =========================================================================
-- 3. Obligations — money that is already spoken for, and money due to arrive
-- =========================================================================
create table if not exists public.obligations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  direction text not null default 'out' check (direction in ('out','in')),
  amount numeric(12,2) not null check (amount > 0),
  cadence text not null default 'monthly'
    check (cadence in ('once','weekly','biweekly','monthly','quarterly','yearly')),
  -- Anchor date: the next (or only) time this lands. Recurrence rolls forward
  -- from here in the app, so a single column covers every cadence.
  next_due date not null,
  account_id uuid references public.accounts(id) on delete set null,
  category text,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists obligations_user_due_idx
  on public.obligations (user_id, next_due);

alter table public.obligations enable row level security;

drop policy if exists "obligations_owner_all" on public.obligations;
create policy "obligations_owner_all" on public.obligations
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- =========================================================================
-- 4. Goals — money that exists but must not be treated as spendable
-- =========================================================================
create table if not exists public.goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  target_amount numeric(12,2) not null check (target_amount > 0),
  saved_amount numeric(12,2) not null default 0 check (saved_amount >= 0),
  target_date date,
  account_id uuid references public.accounts(id) on delete set null,
  priority integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists goals_user_idx on public.goals (user_id, priority);

alter table public.goals enable row level security;

drop policy if exists "goals_owner_all" on public.goals;
create policy "goals_owner_all" on public.goals
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- =========================================================================
-- 5. Balance maintenance, corrected
-- =========================================================================
-- balance = opening_balance
--         + income
--         - expense
--         - transfers sent from this account
--         + transfers received into this account
create or replace function public.recompute_account_balance(p_account uuid)
returns void
language plpgsql
as $$
begin
  update public.accounts a
     set balance = a.opening_balance
       + coalesce((
           select sum(case
                        when t.type = 'Income'   then  t.amount
                        when t.type = 'Expense'  then -t.amount
                        when t.type = 'Transfer' then -t.amount
                      end)
           from public.transactions t
           where t.account_id = a.id
         ), 0)
       + coalesce((
           select sum(t.amount)
           from public.transactions t
           where t.to_account_id = a.id and t.type = 'Transfer'
         ), 0)
   where a.id = p_account;
end;
$$;

-- Recompute every account touched by the row, on both sides of a transfer.
create or replace function public.transactions_balance_trigger()
returns trigger
language plpgsql
as $$
begin
  if (tg_op in ('INSERT','UPDATE')) then
    perform public.recompute_account_balance(new.account_id);
    if new.to_account_id is not null then
      perform public.recompute_account_balance(new.to_account_id);
    end if;
  end if;

  if (tg_op in ('UPDATE','DELETE')) then
    perform public.recompute_account_balance(old.account_id);
    if old.to_account_id is not null then
      perform public.recompute_account_balance(old.to_account_id);
    end if;
  end if;

  return null;
end;
$$;

drop trigger if exists trg_transactions_balance on public.transactions;
create trigger trg_transactions_balance
  after insert or update or delete on public.transactions
  for each row execute function public.transactions_balance_trigger();

-- Editing opening_balance or creating an account must also settle the balance.
create or replace function public.accounts_opening_balance_trigger()
returns trigger
language plpgsql
as $$
begin
  perform public.recompute_account_balance(new.id);
  return null;
end;
$$;

drop trigger if exists trg_accounts_opening_balance on public.accounts;
create trigger trg_accounts_opening_balance
  after update of opening_balance on public.accounts
  for each row
  when (new.opening_balance is distinct from old.opening_balance)
  execute function public.accounts_opening_balance_trigger();

-- =========================================================================
-- 6. Sensible defaults for the accounts created at signup
-- =========================================================================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.accounts (user_id, name, balance, kind, liquidity, sort_order) values
    (new.id, 'Fidelity Account', 0, 'bank',    'liquid', 0),
    (new.id, 'Access Account',   0, 'bank',    'liquid', 1),
    (new.id, 'Mobile Money',     0, 'momo',    'liquid', 2),
    (new.id, 'Cash',             0, 'cash',    'liquid', 3);
  return new;
end;
$$;

-- Settle every existing account once, so balances reflect the corrected formula.
do $$
declare r record;
begin
  for r in select id from public.accounts loop
    perform public.recompute_account_balance(r.id);
  end loop;
end $$;


-- =====================================================================
-- SOURCE: migrations/0004_coach_memory.sql
-- =====================================================================

-- Personal Finance — Coach memory
--
-- The old coach sent one question with no history, so every message started
-- from nothing. These tables give a conversation a past: what was asked, what
-- the coach looked up, and what it offered to do.
--
-- Safe to run more than once. Run after 0002.

create table if not exists public.ai_threads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists ai_threads_user_updated_idx
  on public.ai_threads (user_id, updated_at desc);

alter table public.ai_threads enable row level security;

drop policy if exists "ai_threads_owner_all" on public.ai_threads;
create policy "ai_threads_owner_all" on public.ai_threads
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

create table if not exists public.ai_messages (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references public.ai_threads(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,

  -- 'user'      — what the person typed
  -- 'assistant' — what the coach said, and/or the tools it asked to run
  -- 'tool'      — the result handed back to the coach
  role text not null check (role in ('user','assistant','tool')),

  -- Null on an assistant turn that only requested tools.
  content text,

  -- Tools the assistant asked for, in provider shape, so the thread can be
  -- replayed verbatim on the next request.
  tool_calls jsonb,

  -- Set on 'tool' rows: which request this answers, and which tool ran.
  tool_call_id text,
  name text,

  -- Actions offered to the user on this turn. Nothing here has happened —
  -- these are proposals awaiting a tap.
  actions jsonb,

  created_at timestamptz not null default now()
);

create index if not exists ai_messages_thread_idx
  on public.ai_messages (thread_id, created_at);

alter table public.ai_messages enable row level security;

drop policy if exists "ai_messages_owner_all" on public.ai_messages;
create policy "ai_messages_owner_all" on public.ai_messages
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Keep threads ordered by real activity, not creation.
create or replace function public.touch_ai_thread()
returns trigger
language plpgsql
as $$
begin
  update public.ai_threads
     set updated_at = now()
   where id = new.thread_id;
  return null;
end;
$$;

drop trigger if exists trg_ai_messages_touch on public.ai_messages;
create trigger trg_ai_messages_touch
  after insert on public.ai_messages
  for each row execute function public.touch_ai_thread();


-- =====================================================================
-- SOURCE: migrations/0005_sms_import.sql
-- =====================================================================

-- Personal Finance — SMS import
--
-- Seven accounts, four of which announce every transaction by SMS. Typing those
-- in by hand is the single largest reason the ledger drifts out of date, so the
-- app reads them instead. Only cash stays manual — nothing texts you about cash.
--
-- Three things have to be true for that to be safe:
--
--   1. Importing the same message twice must be impossible, not merely
--      unlikely — hence transactions.external_ref and a unique index.
--   2. Money moving to IC Wealth or Black Star must land as a Transfer, never
--      as spending. Both are funded through MoMo, so their alerts are
--      indistinguishable from paying a shop until a rule says otherwise.
--   3. Nothing may be silently discarded. A message we cannot read is kept in
--      sms_inbox for review, because a parser that quietly drops transactions
--      looks exactly like a quiet month.
--
-- Safe to run more than once. Run after 0004.

-- =========================================================================
-- 1. Where a transaction came from
-- =========================================================================
alter table public.transactions
  add column if not exists source text not null default 'manual',
  -- The bank's own identifier for the movement, qualified by amount and time.
  -- Not the raw reference: Fidelity bills a transfer and its fee as two alerts
  -- sharing one session ID, and CBG's 'Ref' is just the masked account number,
  -- identical on every message it sends. See ParsedSms.dedupeKey.
  add column if not exists external_ref text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'transactions_source_check') then
    alter table public.transactions add constraint transactions_source_check
      check (source in ('manual','sms'));
  end if;
end $$;

-- The guarantee that makes re-scanning the inbox harmless. Partial, because
-- every hand-entered row leaves external_ref null and nulls must not collide.
create unique index if not exists transactions_external_ref_key
  on public.transactions (user_id, external_ref)
  where external_ref is not null;

-- =========================================================================
-- 2. Which account each sender speaks for
-- =========================================================================
create table if not exists public.sms_account_links (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,

  -- Matches BankSmsParser.id: 'fidelity', 'access', 'cbg', 'mtn_momo'.
  parser_id text not null,
  account_id uuid not null references public.accounts(id) on delete cascade,

  -- The user's own numbers as the banks write them: MoMo MSISDN, masked
  -- account numbers. Fidelity's narration for a wallet top-up names the
  -- destination MoMo number, and recognising it as the user's own is what
  -- turns a debit plus an unrelated credit into one transfer.
  identifiers text[] not null default '{}',

  created_at timestamptz not null default now(),
  unique (user_id, parser_id)
);

create index if not exists sms_account_links_account_idx
  on public.sms_account_links (account_id);

alter table public.sms_account_links enable row level security;

drop policy if exists "sms_account_links_owner_all" on public.sms_account_links;
create policy "sms_account_links_owner_all" on public.sms_account_links
  for all using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- =========================================================================
-- 3. What a counterparty means
-- =========================================================================
-- Learned once from the review queue, then applied silently forever. This is
-- what keeps the queue from becoming a second data-entry chore: after a few
-- weeks only genuinely new counterparties surface.
create table if not exists public.sms_routing_rules (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,

  -- Restrict the rule to one sender, or leave null to match any.
  parser_id text,

  -- Counterparty text to look for, upper-cased and space-collapsed the same
  -- way ParsedSms.counterparty is, so 'INTERCITY STC COACHES  LIMITED' and the
  -- name typed normally are one rule rather than two.
  match_text text not null check (length(trim(match_text)) > 0),
  match_kind text not null default 'contains' check (match_kind in ('contains','exact')),

  txn_type text not null check (txn_type in ('Income','Expense','Transfer')),
  category text,

  -- The account at the *other* end of the movement, set only for transfers.
  -- One rule serves both directions: on a debit the money leaves the sender's
  -- account and lands here, on a credit it travels the other way. That is what
  -- makes redeeming an investment income-neutral instead of a fake payday.
  counterpart_account_id uuid references public.accounts(id) on delete cascade,

  -- Higher wins, so a specific merchant can override a broad rule.
  priority integer not null default 0,
  created_at timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'sms_routing_rules_shape_check') then
    alter table public.sms_routing_rules add constraint sms_routing_rules_shape_check
      check (
        (txn_type = 'Transfer' and counterpart_account_id is not null and category is null)
        or
        (txn_type <> 'Transfer' and counterpart_account_id is null and category is not null)
      );
  end if;
end $$;

create index if not exists sms_routing_rules_user_idx
  on public.sms_routing_rules (user_id, priority desc);

create index if not exists sms_routing_rules_counterpart_idx
  on public.sms_routing_rules (counterpart_account_id)
  where counterpart_account_id is not null;

alter table public.sms_routing_rules enable row level security;

drop policy if exists "sms_routing_rules_owner_all" on public.sms_routing_rules;
create policy "sms_routing_rules_owner_all" on public.sms_routing_rules
  for all using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- =========================================================================
-- 4. The review queue
-- =========================================================================
-- Every message the app has seen, whether or not it became a transaction.
-- Keeping the body means a parser fixed next month can re-read what this
-- month's parser could not.
create table if not exists public.sms_inbox (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,

  sender text not null,
  body text not null,
  received_at timestamptz not null,

  -- 'pending'  — read successfully, waiting for a category or a confirmation
  -- 'imported' — became transaction_id
  -- 'ignored'  — deliberately not money, e.g. an OTP or a promo
  -- 'unparsed' — from a known sender in a shape we do not understand yet
  status text not null default 'pending'
    check (status in ('pending','imported','ignored','unparsed')),

  -- What the parser made of it. Null while unparsed.
  parsed jsonb,

  transaction_id uuid references public.transactions(id) on delete set null,

  -- Null while unparsed: a message we cannot read has no amount or reference
  -- to build a key from, and must not block a later one that shares its text.
  dedupe_key text,

  created_at timestamptz not null default now()
);

create unique index if not exists sms_inbox_dedupe_key
  on public.sms_inbox (user_id, dedupe_key)
  where dedupe_key is not null;

create index if not exists sms_inbox_user_status_idx
  on public.sms_inbox (user_id, status, received_at desc);

create index if not exists sms_inbox_transaction_idx
  on public.sms_inbox (transaction_id)
  where transaction_id is not null;

alter table public.sms_inbox enable row level security;

drop policy if exists "sms_inbox_owner_all" on public.sms_inbox;
create policy "sms_inbox_owner_all" on public.sms_inbox
  for all using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));


-- =====================================================================
-- SOURCE: migrations/0006_sms_import_rpc.sql
-- =====================================================================

-- Personal Finance — atomic SMS import
--
-- 0005 built the tables. This builds the one operation the importer cannot
-- express as a sequence of client calls.
--
-- Importing a message writes up to three rows: the transaction, the bank's fee
-- as its own transaction, and the sms_inbox row that marks the message dealt
-- with. Done from Dart that is three round trips, and every gap between them is
-- a state the books should never be in — a fee charged with nothing to explain
-- it, or a message marked imported whose transaction never arrived. A function
-- runs the whole thing inside one statement's transaction, so it either all
-- happens or none of it does.
--
-- Both functions are security invoker (the default), so RLS still applies and a
-- caller can only ever write its own rows. user_id is taken from auth.uid()
-- rather than trusted from the client.
--
-- Safe to run more than once. Run after 0005.

-- =========================================================================
-- Shared: insert one planned transaction, tolerating a re-import
-- =========================================================================
-- Returns the row's id whether this call created it or a previous sweep did.
-- The null-external_ref branch is unreachable from the importer — every planned
-- row carries a dedupe key — but a function that silently skipped the insert if
-- one were ever missing would be a bad way to find that out.
create or replace function public.sms_insert_planned_txn(p_txn jsonb)
returns uuid
language plpgsql
as $$
declare
  v_id  uuid;
  v_ref text := p_txn->>'external_ref';
begin
  if v_ref is null or length(trim(v_ref)) = 0 then
    raise exception 'sms_insert_planned_txn: external_ref is required';
  end if;

  insert into public.transactions (
    user_id, account_id, to_account_id, type, amount,
    category, description, date, source, external_ref
  )
  values (
    (select auth.uid()),
    (p_txn->>'account_id')::uuid,
    nullif(p_txn->>'to_account_id', '')::uuid,
    p_txn->>'type',
    (p_txn->>'amount')::numeric,
    p_txn->>'category',
    nullif(p_txn->>'description', ''),
    (p_txn->>'date')::date,
    'sms',
    v_ref
  )
  on conflict (user_id, external_ref) where external_ref is not null
    do nothing
  returning id into v_id;

  -- Conflict path: the row is already there from an earlier sweep. Return the
  -- existing id so the inbox row still gets pointed at its transaction.
  if v_id is null then
    select id into v_id
    from public.transactions
    where user_id = (select auth.uid()) and external_ref = v_ref;
  end if;

  return v_id;
end;
$$;

-- =========================================================================
-- Import: transaction (+ fee) + inbox row, all or nothing
-- =========================================================================
create or replace function public.sms_import_txn(
  p_sender      text,
  p_body        text,
  p_received_at timestamptz,
  p_dedupe_key  text,
  p_parsed      jsonb,
  p_txn         jsonb,
  p_fee         jsonb default null
)
returns uuid
language plpgsql
as $$
declare
  v_txn_id uuid;
begin
  v_txn_id := public.sms_insert_planned_txn(p_txn);

  -- The fee is a separate ledger row on purpose: folded into the amount, every
  -- merchant total would read a few cedis high forever.
  if p_fee is not null then
    perform public.sms_insert_planned_txn(p_fee);
  end if;

  insert into public.sms_inbox (
    user_id, sender, body, received_at, status, parsed, transaction_id, dedupe_key
  )
  values (
    (select auth.uid()), p_sender, p_body, p_received_at,
    'imported', p_parsed, v_txn_id, p_dedupe_key
  )
  on conflict (user_id, dedupe_key) where dedupe_key is not null
    do update set
      status         = 'imported',
      transaction_id = excluded.transaction_id,
      parsed         = excluded.parsed;

  return v_txn_id;
end;
$$;

-- =========================================================================
-- Review: fee (if any) + a pending inbox row
-- =========================================================================
-- The fee is written even though the transaction it belongs to is still
-- unresolved. A bank charge is unambiguous in a way its merchant is not —
-- holding it back would understate spending for as long as the queue sits
-- unread, which on a busy week is the whole week.
create or replace function public.sms_hold_for_review(
  p_sender      text,
  p_body        text,
  p_received_at timestamptz,
  p_dedupe_key  text,
  p_parsed      jsonb,
  p_fee         jsonb default null
)
returns void
language plpgsql
as $$
begin
  if p_fee is not null then
    perform public.sms_insert_planned_txn(p_fee);
  end if;

  insert into public.sms_inbox (
    user_id, sender, body, received_at, status, parsed, dedupe_key
  )
  values (
    (select auth.uid()), p_sender, p_body, p_received_at,
    'pending', p_parsed, p_dedupe_key
  )
  on conflict (user_id, dedupe_key) where dedupe_key is not null
    do nothing;
end;
$$;

-- =========================================================================
-- Resolve: turn a reviewed message into a transaction
-- =========================================================================
-- Called when the user answers the queue. Same all-or-nothing guarantee: the
-- inbox row flips to 'imported' only if the ledger row landed.
create or replace function public.sms_resolve_review(
  p_inbox_id uuid,
  p_txn      jsonb
)
returns uuid
language plpgsql
as $$
declare
  v_txn_id uuid;
begin
  v_txn_id := public.sms_insert_planned_txn(p_txn);

  update public.sms_inbox
  set status = 'imported', transaction_id = v_txn_id
  where id = p_inbox_id and user_id = (select auth.uid());

  if not found then
    raise exception 'sms_resolve_review: no such message';
  end if;

  return v_txn_id;
end;
$$;


-- =====================================================================
-- SOURCE: migrations/0007_custom_categories.sql
-- =====================================================================

-- Personal Finance — categories the user owns
--
-- The built-in list was a guess, and a guess that does not match how someone
-- actually spends is worse than no list at all: every mismatched transaction
-- ends up under 'Other', and 'Other' explains nothing.
--
-- So categories become rows instead of a constant. Every user gets the old list
-- seeded as ordinary rows they may rename, hide or delete, and may add their
-- own alongside. transactions.category stays free text — nothing here is a
-- foreign key — so hiding or deleting a category never rewrites history or
-- breaks a report. It only decides what the pickers offer next time.
--
-- Safe to run more than once. Run after 0006.

-- =========================================================================
-- 1. The table
-- =========================================================================
create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,

  -- Matches transactions.category verbatim. Renaming here does not touch
  -- existing rows; see rename_category below for the one that does.
  name text not null,

  kind text not null check (kind in ('expense','income')),

  -- A key into kPickableIcons on the client, not a codepoint. Storing the
  -- codepoint would break the moment Material renumbers an icon, and would
  -- also defeat tree-shaking of icon fonts.
  icon text,

  -- Hidden, not deleted: the label a hundred old transactions carry should
  -- stop being offered without disappearing from the ledger.
  is_hidden boolean not null default false,

  -- True for the seeded defaults. Only used to explain them in the UI.
  is_builtin boolean not null default false,

  sort_order int not null default 0,
  created_at timestamptz not null default now(),

  unique (user_id, kind, name)
);

create index if not exists categories_user_kind_idx
  on public.categories (user_id, kind, sort_order);

alter table public.categories enable row level security;

drop policy if exists "categories_owner_all" on public.categories;
create policy "categories_owner_all" on public.categories
  for all using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- =========================================================================
-- 2. Seeding the old constants as rows
-- =========================================================================
create or replace function public.seed_default_categories(p_user uuid)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  -- Security definer, so the argument has to be checked rather than trusted:
  -- without this any signed-in user could seed rows into someone else's list.
  -- auth.uid() is null when the signup trigger calls this, which is the one
  -- legitimate case for seeding a user other than yourself.
  if auth.uid() is not null and p_user <> auth.uid() then
    raise exception 'Not your account';
  end if;

  insert into public.categories (user_id, name, kind, icon, is_builtin, sort_order)
  select p_user, d.name, d.kind, d.icon, true, d.ord
  from (values
    ('Food & Dining',      'expense', 'restaurant',  0),
    ('Transportation',     'expense', 'bus',         1),
    ('Shopping',           'expense', 'shopping',    2),
    ('Entertainment',      'expense', 'movie',       3),
    ('Bills & Utilities',  'expense', 'bolt',        4),
    ('Healthcare',         'expense', 'medical',     5),
    ('Education',          'expense', 'school',      6),
    ('Travel',             'expense', 'flight',      7),
    ('Housing',            'expense', 'home',        8),
    ('Insurance',          'expense', 'shield',      9),
    ('Gifts & Donations',  'expense', 'gift',       10),
    ('Bank Charges',       'expense', 'receipt',    11),
    ('Other',              'expense', 'category',   12),
    ('Salary',             'income',  'work',        0),
    ('Business',           'income',  'business',    1),
    ('Investment',         'income',  'trending_up', 2),
    ('Gift',               'income',  'gift',        3),
    ('Refund',             'income',  'replay',      4),
    ('Other',              'income',  'category',    5)
  ) as d(name, kind, icon, ord)
  on conflict (user_id, kind, name) do nothing;
end;
$$;

-- Existing users get the same list, once.
do $$
declare r record;
begin
  for r in select id from auth.users loop
    perform public.seed_default_categories(r.id);
  end loop;
end $$;

-- New users get it at signup, alongside their starter accounts.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.accounts (user_id, name, balance, kind, liquidity, sort_order) values
    (new.id, 'Fidelity Account', 0, 'bank',    'liquid', 0),
    (new.id, 'Access Account',   0, 'bank',    'liquid', 1),
    (new.id, 'Mobile Money',     0, 'momo',    'liquid', 2),
    (new.id, 'Cash',             0, 'cash',    'liquid', 3);
  perform public.seed_default_categories(new.id);
  return new;
end;
$$;

-- =========================================================================
-- 3. Renaming a category the user has already used
-- =========================================================================
-- Two writes that must not half-happen: the label on the category and the
-- label on every transaction wearing it. Done client-side that is two round
-- trips with a window where reports show both spellings as separate lines.
create or replace function public.rename_category(
  p_id uuid,
  p_new_name text
)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  v_old  text;
  v_kind text;
begin
  select name, kind into v_old, v_kind
  from public.categories
  where id = p_id and user_id = auth.uid();

  if v_old is null then
    raise exception 'Category not found';
  end if;
  if v_old = p_new_name then
    return;
  end if;

  update public.categories set name = p_new_name where id = p_id;

  -- Only rows of the matching direction: an expense 'Other' and an income
  -- 'Other' are different categories that happen to share a label.
  update public.transactions
     set category = p_new_name
   where user_id = auth.uid()
     and category = v_old
     and type = (case when v_kind = 'income' then 'Income' else 'Expense' end);
end;
$$;

-- How many transactions a category is holding, so the UI can warn before a
-- delete instead of after.
create or replace function public.category_usage_count(p_id uuid)
returns integer
language sql
security definer set search_path = public
as $$
  select count(*)::int
  from public.transactions t
  join public.categories c
    on c.id = p_id
   and c.user_id = auth.uid()
  where t.user_id = auth.uid()
    and t.category = c.name
    and t.type = (case when c.kind = 'income' then 'Income' else 'Expense' end);
$$;

grant execute on function public.seed_default_categories(uuid) to authenticated;
grant execute on function public.rename_category(uuid, text)   to authenticated;
grant execute on function public.category_usage_count(uuid)    to authenticated;


-- =====================================================================
-- SOURCE: migrations/0008_sms_ignore.sql
-- =====================================================================

-- Personal Finance — ignoring non-money messages
--
-- 0005 keeps every message from a linked sender, by design: a parser that
-- quietly drops transactions looks exactly like a quiet month. But a linked
-- sender also texts OTPs, promos and bundle notices, and those must not pile
-- up in the review queue — they are money-adjacent at best, and the queue is
-- only useful while everything in it deserves a human's answer.
--
-- The Dart parser classifies those messages as 'not money' before any
-- transaction is considered. This gives that classification the same
-- all-or-nothing write path the importer and the review queue have, so
-- re-scanning the inbox stays idempotent for them too.
--
-- Safe to run more than once. Run after 0006.

create or replace function public.sms_ignore_message(
  p_sender      text,
  p_body        text,
  p_received_at timestamptz,
  p_dedupe_key  text
)
returns void
language plpgsql
as $$
begin
  insert into public.sms_inbox (
    user_id, sender, body, received_at, status, dedupe_key
  )
  values (
    (select auth.uid()), p_sender, p_body, p_received_at,
    'ignored', p_dedupe_key
  )
  on conflict (user_id, dedupe_key) where dedupe_key is not null
  do nothing;
end;
$$;


-- =====================================================================
-- SOURCE: migrations/0009_harden_function_security.sql
-- =====================================================================

-- Personal Finance — close two gaps the Supabase linter found
--
-- Neither is a new bug. Both have been true since the functions were written;
-- they only became visible when the schema was stood up on a fresh project and
-- the security advisor was run against it.
--
-- INCOMPLETE ON ITS OWN — see 0010. The search_path half of this migration
-- worked. The revokes in section 1 did not: PostgreSQL grants EXECUTE to the
-- PUBLIC pseudo-role when a function is created, and `revoke ... from anon`
-- leaves that grant in place, so anon kept reaching every function through it.
-- 0010 revokes from PUBLIC and grants back explicitly. This file is kept as
-- applied rather than rewritten, so the repo and the deployed history match.
--
-- Safe to run more than once. Run after 0008.

-- =========================================================================
-- 1. seed_default_categories must not be callable by anon
-- =========================================================================
-- The function is `security definer`, so it writes with the owner's rights, and
-- it guards its argument with:
--
--     if auth.uid() is not null and p_user <> auth.uid() then raise ...
--
-- For a signed-in caller that is exactly right. For an unauthenticated one it
-- is not: auth.uid() is null, the left side of the `and` is false, the whole
-- condition is false, and the guard waves the call through. Since PostgREST
-- exposes every function in `public` as an endpoint, anyone holding the anon
-- key could POST /rest/v1/rpc/seed_default_categories with any user id and
-- seed category rows into that person's list.
--
-- The null case is reachable on purpose — the signup trigger calls this with
-- auth.uid() still null, which is the one legitimate reason to seed somebody
-- other than yourself. So the guard stays as it is and the fix is to take the
-- endpoint away from anon instead. `authenticated` keeps it: the app calls this
-- from CategoryRepository to re-seed a user's own defaults.
revoke execute on function public.seed_default_categories(uuid) from anon;

-- Same treatment for the other two the app calls as a signed-in user. Their
-- own guards are sound (both filter on `user_id = auth.uid()`, which matches
-- nothing when auth.uid() is null), so this is defence in depth rather than a
-- hole being closed.
revoke execute on function public.rename_category(uuid, text)   from anon;
revoke execute on function public.category_usage_count(uuid)    from anon;

-- handle_new_user is a trigger function and nothing should ever reach it
-- through the API. Calling it directly fails anyway — PostgreSQL refuses to run
-- a trigger function outside a trigger — but an endpoint that exists only to
-- return an error is still an endpoint. Revoking EXECUTE does not stop the
-- trigger firing: PostgreSQL checks EXECUTE when the trigger is created, not
-- each time it fires, and the insert into auth.users is made by
-- supabase_auth_admin regardless.
revoke execute on function public.handle_new_user() from anon, authenticated;

-- =========================================================================
-- 2. Pin search_path on the functions that lack it
-- =========================================================================
-- These nine are `security invoker`, so they carry less risk than a definer
-- function would — but an unpinned search_path still means the objects a body
-- resolves to depend on whoever is calling it. Every body here already
-- schema-qualifies what it touches (public.*, auth.uid()), so pinning changes
-- no behaviour; it just stops that being true only by accident.
--
-- ALTER rather than CREATE OR REPLACE on purpose: the bodies are correct and
-- restating them here would leave two copies of each to keep in step.
alter function public.recompute_account_balance(uuid)
  set search_path = public, pg_temp;

alter function public.transactions_balance_trigger()
  set search_path = public, pg_temp;

alter function public.accounts_opening_balance_trigger()
  set search_path = public, pg_temp;

alter function public.touch_ai_thread()
  set search_path = public, pg_temp;

alter function public.sms_insert_planned_txn(jsonb)
  set search_path = public, pg_temp;

alter function public.sms_import_txn(text, text, timestamptz, text, jsonb, jsonb, jsonb)
  set search_path = public, pg_temp;

alter function public.sms_hold_for_review(text, text, timestamptz, text, jsonb, jsonb)
  set search_path = public, pg_temp;

alter function public.sms_resolve_review(uuid, jsonb)
  set search_path = public, pg_temp;

alter function public.sms_ignore_message(text, text, timestamptz, text)
  set search_path = public, pg_temp;


-- =====================================================================
-- SOURCE: migrations/0010_fix_function_grants.sql
-- =====================================================================

-- Personal Finance — make 0009's revokes actually bite
--
-- 0009 ran `revoke execute ... from anon` and reported success, but the anon
-- role could still call every one of those functions afterwards.
--
-- The reason is a PostgreSQL default that is easy to miss: on creation, a
-- function is granted EXECUTE to PUBLIC — the pseudo-role every other role
-- inherits from. Revoking the privilege from `anon` removes a grant `anon`
-- never had directly, and leaves it reaching the function through PUBLIC. The
-- revoke has to name PUBLIC, and then the roles that *should* keep the function
-- need it granted back explicitly.
--
-- Checked with has_function_privilege('anon', oid, 'EXECUTE') rather than by
-- reading the migration back, which is what caught this in the first place.
--
-- Safe to run more than once. Run after 0009.

-- =========================================================================
-- Functions the app calls as a signed-in user
-- =========================================================================
-- authenticated keeps these; anon loses them. seed_default_categories is the
-- one that mattered: its `auth.uid() is not null and p_user <> auth.uid()`
-- guard passes for an unauthenticated caller, so reaching it without a session
-- let category rows be written for any user id (see 0009 for the full reading).
revoke execute on function public.seed_default_categories(uuid) from public, anon;
grant  execute on function public.seed_default_categories(uuid) to authenticated;

revoke execute on function public.rename_category(uuid, text) from public, anon;
grant  execute on function public.rename_category(uuid, text) to authenticated;

revoke execute on function public.category_usage_count(uuid) from public, anon;
grant  execute on function public.category_usage_count(uuid) to authenticated;

-- =========================================================================
-- The signup trigger function
-- =========================================================================
-- Nothing should reach this through the API, so no API role keeps it.
--
-- supabase_auth_admin is granted it explicitly, which is the belt to the
-- braces: GoTrue connects as that role to insert into auth.users, and until now
-- it held EXECUTE only by way of the PUBLIC grant this statement removes.
-- PostgreSQL checks EXECUTE on a trigger function when the trigger is created
-- rather than each time it fires, so in principle the revoke alone is harmless
-- — but "in principle" is a poor thing to rest signup on, and an explicit grant
-- costs nothing. postgres keeps access as the function's owner.
revoke execute on function public.handle_new_user() from public, anon, authenticated;
grant  execute on function public.handle_new_user() to supabase_auth_admin;
